self.KB_CONTENT["card:752044"]={"id":"card:752044","ty":"card","sourceId":"752044","title":"『會計異常檢核表』中的『選擇檢查會計期別』為何？","ver":"iGP","topic":"檢核","keywords":["檢核"],"y":"other","answer":"* 此欄位不可空白。* 若會計期制為 12 期時，則只能輸 01~12，會計期制為 13 期時，則只能輸 01~13。","links":[],"pdfText":"","pdfPages":0,"pdfChars":0,"merged":[],"file":"kb-cards.jsonl"};
