self.KB_CONTENT["card:751715"]={"id":"card:751715","ty":"card","sourceId":"751715","title":"『帳別資料對應建立作業』中的『損益類科目類別/目的科目類別 (ACT.MA008)』為何？","ver":"iGP","topic":"明細","keywords":["明細","科目","類別","分類"],"y":"other","answer":"* 顯示該筆會計科目的科目類別為1.統制帳戶、2.明細帳戶、3.獨立帳戶或4.分類。","links":[],"pdfText":"","pdfPages":0,"pdfChars":0,"merged":[],"file":"kb-cards.jsonl"};
