self.KB_CONTENT["card:783420"]={"id":"card:783420","ty":"card","sourceId":"783420","title":"『載入轉換用新會計科目作業』中的『新舊統制帳戶科目自動對應』為何？","ver":"GP4以上","topic":"科目","keywords":["科目","清除"],"y":"other","answer":"* 僅Y/N，預設Y。* 因科目資料中存有「科目層級」，所以每次載入時，都會先清除已存在的科目主檔資料，再行載入。","links":[],"pdfText":"","pdfPages":0,"pdfChars":0,"merged":[],"file":"kb-cards.jsonl"};
