self.KB_CONTENT["card:779928"]={"id":"card:779928","ty":"card","sourceId":"779928","title":"『生產入庫單憑證(IDL)』中的『選擇確認狀態 (TF006)』為何？","ver":"GP4以上","topic":"入庫單","keywords":["入庫單","憑證","生產","狀態"],"y":"other","answer":"* 分為Y.已確認、N.未確認、V.作廢及全部四種確認狀態。","links":[],"pdfText":"","pdfPages":0,"pdfChars":0,"merged":[],"file":"kb-cards.jsonl"};
