self.KB_CONTENT["field:793722"]={"id":"field:793722","ty":"field","sourceId":"793722","title":"單據日期","ver":"GP4以上","topic":"","keywords":[],"job":"外修回報單建立作業","code":"TP021","answer":"* 此欄位不可空白。* 輸入的日期須大於等於庫存現行年月。* 連續新增此單據時，系統自動預設前一筆的單據日期。","file":"fields.jsonl"};
