self.KB_CONTENT["field:785088"]={"id":"field:785088","ty":"field","sourceId":"785088","title":"輸入單身序號間隔","ver":"GP4以上","topic":"","keywords":[],"job":"固定資產產生底稿作業","code":"","answer":"* 預設每10筆單身序號為間隔。亦可修改，但不可空白。* 此欄位僅可輸入1~10之數值。","file":"fields.jsonl"};
