self.KB_CONTENT["field:830052"]={"id":"field:830052","ty":"field","sourceId":"830052","title":"平均月折舊額","ver":"GP4.0.6.0 以上","topic":"","keywords":[],"job":"資產資料建立作業","code":"","answer":"當資產攤提到最後一個月，且『資產資料建立作業』【折舊資料】頁籤中【預留殘值】為0，系統會將剩餘折舊金額在最後一個月一次性攤提，因此最後一個月的折舊費用會和【平均月折舊額】不一致。","file":"fields.jsonl"};
