self.KB_CONTENT["field:838166"]={"id":"field:838166","ty":"field","sourceId":"838166","title":"應付單號","ver":"GP4 以上","topic":"","keywords":[],"job":"資產資料建立作業","code":"","answer":"『資產資料建立作業』單頭的【應付單號】是由『應付憑單建立作業』單身【來源】選\"7.資產取得\"，在【憑證單別】開窗去選擇該資產的取得單別單號，再將應付憑單確認後所回寫。","file":"fields.jsonl"};
