self.KB_CONTENT["field:861551"]={"id":"field:861551","ty":"field","sourceId":"861551","title":"數量","ver":"GP4.0.24.1以上","topic":"","keywords":[],"job":"BOM用量建立作業","code":"","answer":"『BOM用量建立作業』單身的【組成用量】為分子，【底數】為分母。表示一個主件需要用到多少元件的數量換算。 舉例：產品品號當要生產1個時，需要半成品0.5個，則在設定BOM單身時，針對半成品的組成用量就可設定1，底數設為2。 『取替代料件建立作業』單身的【數量】，指的是單身可取代的料件的數量要幾個才可取替帶原材料。 舉例：1個單頭A元件可以用0.5個單身B元件取替代，則單身數量為0.5。","file":"fields.jsonl"};
