self.KB_CONTENT["field:777636"]={"id":"field:777636","ty":"field","sourceId":"777636","title":"選擇彙總方式","ver":"GP4以上","topic":"","keywords":[],"job":"MOCR22 料件預計領用表","code":"","answer":"* 可以選擇需要列印之彙總方式。方式有1.明細、2.日、3.週、4.旬、5.半月及6.一月。","file":"fields.jsonl"};
